} from 'ckeditor5';

import FileLink from '../src/plugins/filelink/filelink.js';
import InsertImage from '../src/plugins/insertimage/insertimage.js';
import PageLink from '../src/plugins/pagelink/pagelink.js';
import SignalR from '../src/plugins/signalr/signalr.js';
import VSCodeEditor from '../src/plugins/vscodeeditor/vscodeeditor.js';
import { getToolbarProfile } from '../src/toolbarProfiles.js';

const SIMPLE_EDITOR_TYPES = new Set(['title', 'heading']);
const ADVANCED_EDITOR_TYPES = new Set(['ckeditor', 'default', 'richtext']);

export function getRuntimeProfileName(runtimeWindow = window, editorElement = null) {
    // Explicit runtime override takes precedence over inferred mapping.
    const explicitProfile = runtimeWindow?.skycmsEditorProfile
        || runtimeWindow?.ccmsCkeditorProfile
        || runtimeWindow?.CCMS_CKEDITOR_PROFILE
        || runtimeWindow?.ccmsEditorConfig?.profile;

    if (explicitProfile) {
        return explicitProfile;
    }

    const editorType = editorElement?.getAttribute?.('data-editor-config')?.toLowerCase();

    if (editorType && SIMPLE_EDITOR_TYPES.has(editorType)) {
        return 'simple';
    }

    if (editorType && ADVANCED_EDITOR_TYPES.has(editorType)) {
        return 'advanced';
    }

    return 'simple';
}

export function createPlaygroundConfig(profileName = 'simple') {
    return {
        licenseKey: 'GPL',
        // Keep plugin registrations broad so profile changes only affect UI exposure.
        plugins: [
            Essentials,
            Paragraph,
            Heading,
            Autoformat,
            Bold,
            Italic,
            Underline,
            Link,
            LinkImage,
            List,
            ListProperties,
            BlockQuote,
            CodeBlock,
            Undo,
            ImageBlock,
            ImageCaption,
            ImageInline,
            ImageInsert,
            ImageInsertViaUrl,
            ImageResize,
            ImageStyle,
            ImageTextAlternative,
            ImageToolbar,
            FileLink,
            InsertImage,
            PageLink,
            SignalR,
            VSCodeEditor
        ],
        toolbar: {
            items: getToolbarProfile(profileName)
        },
        image: {
            toolbar: [
                'toggleImageCaption',
                'imageTextAlternative',
                '|',
                'imageStyle:inline',
                'imageStyle:wrapText',
                'imageStyle:breakText',
                '|',
                'resizeImage'
            ]
        }
    };
}

export function startPlaygroundEditor({
    runtimeWindow = window,
    runtimeDocument = document,
    editorClass = InlineEditor
} = {}) {
    const editorElement = runtimeDocument.querySelector('#editor');

    if (!editorElement) {
        console.warn('SkyCMS playground: #editor element not found.');
        return Promise.resolve(null);
    }

    const profileName = getRuntimeProfileName(runtimeWindow, editorElement);
    const config = createPlaygroundConfig(profileName);

    return editorClass.create(editorElement, config)
        .then(editor => {
            console.log(`SkyCMS playground editor ready (profile: ${profileName}).`);
            return editor;
        })
        .catch(error => {
            console.error('Failed to start SkyCMS playground editor:', error);
            throw error;
        });
}

