// Reduced icon payload for local integration package.
const editCodeIcon = "<svg viewBox='0 0 20 20' xmlns='http://www.w3.org/2000/svg'><path d='M3.6 4.6h12.8c.44 0 .8.36.8.8v9.2c0 .44-.36.8-.8.8H3.6a.8.8 0 0 1-.8-.8V5.4c0-.44.36-.8.8-.8zm.8 1.6v7.6h11.2V6.2H4.4zm2.47 1.53 1.13 1.13-1.13 1.14.57.56 1.69-1.7a.8.8 0 0 0 0-1.13L7.44 7.17l-.57.56zm5.69-.56-.57-.56-1.69 1.7a.8.8 0 0 0 0 1.13l1.7 1.7.56-.56-1.13-1.14 1.13-1.13z'/></svg>";

// Expected host API on window.parent:
//   window.parent.openVsCodeBlockEditor(editor)
//
// The host controls the external code editing experience and applies changes
// back into the CKEditor instance.
export default class VSCodeEditorUI extends Plugin {
    static get pluginName() {
        return 'VSCodeEditor';
    }

    init() {
        const editor = this.editor;
        const t = editor.t;

        editor.ui.componentFactory.add('vsCodeEditor', locale => {
            const button = new ButtonView(locale);

            button.set({
                label: t('Open code editor.'),
                icon: editCodeIcon,
                tooltip: true
            });

            this.listenTo(button, 'execute', () => {
                if (window.parent && window.parent.openVsCodeBlockEditor) {
                    window.parent.openVsCodeBlockEditor(editor);
                } else {
                    alert('No host VS Code editor bridge detected.');
                }
            });

            return button;
        });
    }
}
